INSERT INTO formulacion_144
 (id, formulario_id, nombre_borrador, anio, linea_estrategica, objetivo, estrategia, motor_desarrollo, proyecto, meta_resultado, ponderacion_proyectos, actividad_proyecto, ponderacion_actividades, responsable_formulacion, id_indicador, gestionado_facultades, nombre_indicador, formula_medicion, frecuencia_medicion, unidad_medida, tipo_medicion, descripcion_indicador, planes_institucionales, linea_base_meta, anio_base_meta, meta_s1, meta_s2, meta_programada, meta_ejecutada, porcentaje_avance, semestre1_seguimiento, semestre2_seguimiento, logros, limites, observacion_estado, acciones_fortalecimiento, estado_formulacion, estado_seguimiento, solicitud_estado_formulacion, solicitud_estado_seguimiento, semaforo_etapa_formulacion, semaforo_etapa_seguimiento, semaforo_rechazo_etapa_formulacion, semaforo_rechazo_etapa_seguimiento, fecha_publicacion_formulacion, creado_por)
VALUES
(@base+1, @formulario, 'Nivel de suficiencia en idiomas B2 de los docentes de carrera profesoral', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '3.Fortalecer los procesos de internacionalización, movilidad, multilingüismo e interculturalidad que visibilicen la Universidad a nivel nacional e internacional, y alcanzar un posicionamiento académico.', 'Internacionalización y multilingüismo.', 'Multilingüismo e interculturalidad', 'Lograr por lo menos el 65% de los docentes de carrera profesoral certificados en nivel suficiencia en idiomas con nivel B2', 9.00, 'Promover la formación en inglés en nuestros docentes', 33.30, 'Vicerrectoría de Docencia', 'PDI', '0', 'Nivel de suficiencia en idiomas B2 de los docentes de carrera profesoral', 'N° de docentes de carrera profesoral certificados con nivel B2 en suficiencia en idiomas  / total de docentes de carrera profesoral * 100', 'Anual', 'Porcentaje', 'Último valor reportado', 'La meta para este año es del 6%, lo que equivale a incrementar en cinco (5) docentes adicionales para alcanzar dicho objetivo.', '[]', '4%', 6, '0%', '6%', '6.00', '3.00', 50.00, 3.00, NULL, 'Desde el Programa de Formación Docente se implementó como estrategia un censo de caracterización del nivel de competencia en lengua extranjera de los docentes de carrera, realizado a través del Sistema de Encuesta Online de la Universidad. Como resultado, se evidenció que, de un total de 339 docentes de carrerad edla Universidad , 11 cuentan con certificación en los niveles B1 y B2, lo que corresponde aproximadamente al 3,24 % del total.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+2, @formulario, 'Estudiantes formados mediante la Política de Enseñanza aprendizaje y evaluación de Lenguas Extranjeras', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '3.Fortalecer los procesos de internacionalización, movilidad, multilingüismo e interculturalidad que visibilicen la Universidad a nivel nacional e internacional, y alcanzar un posicionamiento académico.', 'Internacionalización y multilingüismo.', 'Multilingüismo e interculturalidad', 'Garantizar la Política de Enseñanza aprendizaje y evaluación de Lenguas Extranjeras para que mínimo 5.324 estudiantes logren culminar los cursos de inglés establecidos, asimismo que 199 estudiantes de Licenciatura en Lenguas Extranjeras se formen mediante el Programa de Inmersión en inglés', 9.00, 'Gestionar la realización de actividades institucionales con componente multilingüe e intercultural para la comunidad estudiantil', 33.30, 'Vicerrectoría de Docencia', 'PDI', '0', 'Estudiantes formados mediante la Política de Enseñanza aprendizaje y evaluación de Lenguas Extranjeras', 'N° de estudiantes que culminaron los cursos de inglés establecidos en la Política de Enseñanza aprendizaje y evaluación de Lenguas Extranjeras', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '1727', 485, '0', '485', '485.00', '0.00', 0.00, 0.00, NULL, '', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+3, @formulario, 'Estudiantes formados mediante la Política de Enseñanza aprendizaje y evaluación de Lenguas Extranjeras', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '4.Asegurar la sostenibilidad de la Política de Enseñanza, Aprendizaje y Evaluación de Lenguas Extranjeras de la Universidad del Atlántico.', 'Internacionalización y multilingüismo.', 'Multilingüismo e interculturalidad', 'Garantizar la Política de Enseñanza aprendizaje y evaluación de Lenguas Extranjeras para que mínimo 5.324 estudiantes logren culminar los cursos de inglés establecidos, asimismo que 199 estudiantes de Licenciatura en Lenguas Extranjeras se formen mediante el Programa de Inmersión en inglés', 9.00, 'Promover la formación en inglés en nuestros estudiantes', 33.30, 'Oficina de Rel. Interinst. e Internacionales', 'PDI', '0', 'Estudiantes formados mediante la Política de Enseñanza aprendizaje y evaluación de Lenguas Extranjeras', 'N° de estudiantes formados mediante el Programa de Inmersión en inglés para Estudiantes de Licenciatura en Lenguas Extranjeras', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '100', 20, '0', '20', '20.00', '25.00', 125.00, 25.00, NULL, 'Se cumplió la meta establecida en el Plan de Acción, que contemplaba el envío de 20 estudiantes al programa de inmersión en inglés en la University of British Columbia (UBC), Canadá. Se logró beneficiar a 25 estudiantes, del programa de Licenciatura en Lenguas Extranjeras con énfansis en Inglés y Francés, permitiéndoles fortalecer sus competencias, desarrollar habilidades interculturales y vivir una experiencia académica internacional de alto impacto. Este resultado representa un 125 % de cumplimiento de la meta, reflejando el compromiso institucional con la internacionalización y la formación integral de los estudiantes.', 'Aunque el programa fue formulado para ejecutarse durante la vigencia 2025, su desarrollo se vio afectado por incovenientes en los procesos de visado requeridos para el ingreso de los estudiantes a Canadá. Esta situación, ajena a la gestión de la Universidad, impidió que la movilidad internacional se realizara dentro del cronograma inicialmente previsto, por lo que fue necesario reprogramar la ejecución del Programa de Inmersión en Inglés para el primer semestre (2026-1). No obstante, gracias al seguimiento permanente, la coordinación interinstitucional y el acompañamiento brindado a los estudiantes durante todo el proceso, fue posible llevar a cabo la movilidad de manera exitosa, garantizando el cumplimiento de los objetivos del programa.', 'La actividad fue ejecutada conforme al cronograma ajustado, garantizando el cumplimiento del indicador mediante el seguimiento permanente a cada una de las etapas del programa de inmersión, desde la selección de los beneficiarios hasta la culminación de la movilidad internacional.', 'Consolidar mecanismos de seguimiento y acompañamiento permanente a los estudiantes seleccionados durante todas las etapas del programa, desde la preparación documental hasta la culminación de la movilidad académica. 2.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+4, @formulario, 'Movilidad estudiantil nacional entrante', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '3.Fortalecer los procesos de internacionalización, movilidad, multilingüismo e interculturalidad que visibilicen la Universidad a nivel nacional e internacional, y alcanzar un posicionamiento académico.', 'Internacionalización y multilingüismo.', 'Movilidad académica estudiantil y docente', 'Propender por la movilidad de al menos 17.000 estudiantes desde y hacia la Universidad del Atlántico', 12.00, 'Impulsar la movilidad estudiantil a nivel nacional', 15.00, 'Oficina de Rel. Interinst. e Internacionales', 'PDI', '0', 'Movilidad estudiantil nacional entrante', 'N° de estudiantes nacionales entrantes a la Universidad del Atlántico, desde las funciones sustantivas docencia, extensión, proyección social, Bienestar Universitario e Internacionalización', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '850', 300, '0', '300', '300.00', '73.00', 24.33, 73.00, NULL, '30 estudiantes participaron en actividades de dcoencia en el programa de Contaduria de la facultad de ciencias eonomicas \n43 estudiantes entrantes de la Universidad de Cordoba a la Facultad de ingenieria en en el evento Fortalecer los procesos de formación académica y práctica de los estudiantes visitantes mediante el reconocimiento de la infraestructura, laboratorios especializados y procesos desarrollados en el Programa de Ingeniería Agroindustrial', 'l número de estudiantes participantes aún es bajo frente a la meta anual de 300 estudiantes. La participación se concentra en actividades puntuales y en pocas facultades, pero se ve que se limita el reporte por la falta de entrega por alfunas facultades de la información.', 'Durante el período se registró la participación de 73 estudiantes en actividades de movilidad entrante nacional: 30 estudiantes en actividades de docencia del Programa de Contaduría Pública de la Facultad de Ciencias Económicas y 43 estudiantes de la Universidad de Córdoba que participaron en actividades académicas y de reconocimiento de infraestructura y laboratorios del Programa de Ingeniería Agroindustrial de la Facultad de Ingeniería. Estos resultados evidencian el fortalecimiento de la cooperación académica entre instituciones, aunque se requiere ampliar la participación de otras facultades para alcanzar la meta institucional.', 'Incrementar la promoción de la movilidad entrante nacional entre las instituciones aliadas y redes académicas.\n- Incentivar a las facultades para que programen actividades académicas susceptibles de recibir estudiantes visitantes y al compromiso del reporte de movilidades.\n- Fortalecer la articulación con los programas académicos para planificar visitas, prácticas, cursos cortos y experiencias académicas durante todo el año.\n- Identificar nuevas instituciones de educación superior para establecer alianzas que incrementen el flujo de estudiantes entrantes.\n- Realizar seguimiento periódico al cumplimiento del indicador y establecer estrategias de captación cuando el avance sea inferior al esperado.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+5, @formulario, 'Movilidad estudiantil nacional saliente', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '3.Fortalecer los procesos de internacionalización, movilidad, multilingüismo e interculturalidad que visibilicen la Universidad a nivel nacional e internacional, y alcanzar un posicionamiento académico.', 'Internacionalización y multilingüismo.', 'Movilidad académica estudiantil y docente', 'Propender por la movilidad de al menos 17.000 estudiantes desde y hacia la Universidad del Atlántico', 12.00, 'Impulsar la movilidad estudiantil a nivel nacional', 15.00, 'Oficina de Rel. Interinst. e Internacionales', 'PDI', '0', 'Movilidad estudiantil nacional saliente', 'N° de estudiantes de la Universidad del Atlántico que realizaron movilidad saliente nacional, desde las funciones sustantivas docencia, extensión, proyección social, bienestar universitario e internacionalización', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '6961', 1300, '0', '1300', '1300.00', '195.00', 15.00, 195.00, NULL, '2 estudiantes de la Facultad de bellas artes del programa de Danza,hicieron movilidad saliente al Taller sobre el Carnaval entre asab y la UA Programa Danza, en la ciudad de Bogotá.\n6 estudiantes del programa de danza de la facultad  de bellas artes, estuvieron en misión académica en la ciudad de bogota.\n32 estudiantes del programa de Licenciatura en ducacion especial estuvieron en visita academica en la ciudad de cartagena en la Corporación Educativa Mente Activa.\n4 estudiantes de la facultad de ciencia sbasicas del progama de Biologia asistieron al XIII Congreso latinoamericano de malacología (CLAMA 2026) \n4 estudiantes de la facultad de Bellas Artes del programa de Danza asistieron a mision académica en la ciudad de Bogotá.\n1 estudiante de la Facultad de Bellas Artes del prgrama de danza asistio a estancia de investigación en casa de cultura en zapayan Magdalena.\n54 estudiantes de la Facultad de Bellas Artes del programa de Artes plasticas asistieron a visita de campo en la cidad de cartagena ASIGNATURAS RENACIMIENTO Y BARROCO IV SEM. ANTEPROYECTO DE INVESTIGACIÓN V SEM.\n82 estudiantes de la Facultad de Ciencias Economicas del programa de Contaduria Publica asistieron a Evento Académico en la ciudad de Cartagena.', 'El avance del indicador es del 15 %, evidenciando una brecha importante frente a la meta anual. La participación se concentra principalmente en la Facultad de Bellas Artes, con una menor representación de otras facultades y programas académicos, lo cual se convierte en una limitante para el seguimeinto de medición.', 'Durante el período se registró la participación de 113 estudiantes en actividades de movilidad saliente nacional, destacándose misiones académicas, visitas de campo, estancias de investigación, congresos y talleres desarrollados en Bogotá, Cartagena y Magdalena. La mayor participación correspondió a la Facultad de Bellas Artes, seguida por la Facultad de Ciencias de la Educación y la Facultad de Ciencias Básicas. Estas actividades contribuyen al fortalecimiento de las competencias académicas, investigativas y culturales de los estudiantes, aunque es necesario ampliar la participación de otras facultades para lograr un mayor avance del indicador.', 'Fortalecer el proceso de reporte oportuno de las actividades de movilidad realizadas por las facultades para garantizar el registro completo del indicador.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+6, @formulario, 'Movilidad estudiantil internacional entrante', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '3.Fortalecer los procesos de internacionalización, movilidad, multilingüismo e interculturalidad que visibilicen la Universidad a nivel nacional e internacional, y alcanzar un posicionamiento académico.', 'Internacionalización y multilingüismo.', 'Movilidad académica estudiantil y docente', 'Propender por la movilidad de al menos 17.000 estudiantes desde y hacia la Universidad del Atlántico', 12.00, 'Impulsar la movilidad estudiantil a nivel internacional', 15.00, 'Oficina de Rel. Interinst. e Internacionales', 'PDI', '0', 'Movilidad estudiantil internacional entrante', 'N° de estudiantes extranjeros que realizaron movilidad a la Universidad del Atlántico', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '110', 20, '0', '20', '20.00', '1.00', 5.00, 1.00, NULL, '1 caterin Lobo estudiante del programa Flacso Ecuador en proceso de estancia de investigación con el programa de Historia de la Facultad de Ciencias Humanas.', 'El avance del indicador duante el seguimiento al primer periodo  es bajo (5 %) frente a la meta anual. La movilidad entrante internacional depende de la consolidación de convenios internacionales, los calendarios académicos de las instituciones socias, asi mismo las movilidades entrantes se vieron afectadas por el paro académico del 2025-2.', 'Durante el período se registró el ingreso de 1 estudiante internacional, Caterin Lobo, del programa FLACSO Ecuador, quien se encuentra en proceso de estancia de investigación con el Programa de Historia de la Facultad de Ciencias Humanas. Esta actividad fortalece la cooperación académica internacional y contribuye a la internacionalización de la investigación y al intercambio de conocimientos entre instituciones de educación superio, a traves de la ORII.', 'Intensificar la promoción internacional de la Universidad del Atlántico y de su oferta de estancias de investigación, movilidad académica y cursos para estudiantes extranjeros.\n.Consolidar y dinamizar los convenios internacionales vigentes, promoviendo convocatorias de movilidad entrante.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+7, @formulario, 'Movilidad estudiantil internacional saliente', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '3.Fortalecer los procesos de internacionalización, movilidad, multilingüismo e interculturalidad que visibilicen la Universidad a nivel nacional e internacional, y alcanzar un posicionamiento académico.', 'Internacionalización y multilingüismo.', 'Movilidad académica estudiantil y docente', 'Propender por la movilidad de al menos 17.000 estudiantes desde y hacia la Universidad del Atlántico', 12.00, 'Impulsar la movilidad estudiantil a nivel internacional', 15.00, 'Oficina de Rel. Interinst. e Internacionales', 'PDI', '0', 'Movilidad estudiantil internacional saliente', 'N° de estudiantes de la Universidad del Atlántico que realizaron movilidad saliente internacional, desde las funciones sustantivas docencia, extensión, proyección social, bienestar universitario e internacionalización', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '235', 60, '0', '60', '60.00', '42.00', 70.00, 42.00, NULL, '1 estudiantes de la Facultad de Cienias Economicas del prpgrama de tecnologo en gestión turistica en proceso de movilidad por intercambio académico con las universidades de Jaén en España,\n6 estudiantes de la Facultad de ingenieria de los programas de Ingenieira Industrial, agroindustrial asistieron al  campamento de verano 2026 en Beihang International Summer School.\n25 estudiantes desarrollaron proceso de movilidad a traves del programa de inmersión de lenguas extranejras con la UBC en canadá,\n4 estudiantes de la facultad de ciencias basicas del programa de Qimica asisteron como ponentes al I encuentro internacional de semilleros de investigación - EISI Paraguay 2026.\n1 estudiante del programa de Qumica de la Facultad de Ciencias Basicas asistio como ponenete al Encuentro de semilleros de investigación RedCOLSI EISI en España.\n\n1 estudiante del programa de Qumica de la Facultad de Ciencias Basicas asistio como ponenete al 1er encuentro internacional de semilleros de investigación RedCOLSI - EISI España 2026.\n2 estudiantes del programa de Biologia asistieron a psantia de nvestigaicón a traves del 1 Verano de la investigación cientifica y tecnologica del pacifico del programa delfin.\n1 estudiante de la Facultad de Bellas Artes del programa de danza asistio al Festival Cultural Internacional de la Danza y El Brinco del Chinelo en México\n1 estudiante de la Maestría en Ciencias Físicas del SUE Caribe, Andrea Barros Sarmiento, representaron a la institución en la XXXII Conferencia Internacional de Física y Astrofísica de Neutrinos (Neutrino 2026). El evento tuvo lugar en la Universidad de California, en Irvine (EE. UU.), del 21 al 26 de junio de 2026.', 'Aunque el indicador presenta un avance significativo (68,3 %), aún se requiere incrementar la participación estudiantil para alcanzar la meta anual. La movilidad internacional continúa condicionada por factores el reporte por parte de las facultades.', 'Continuar promoviendo las convocatorias de movilidad internacional y socializarlas oportunamente en todas las facultades.', 'Continuar promoviendo las convocatorias de movilidad internacional y socializarlas oportunamente en todas las facultades.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+8, @formulario, 'Movilidad docente internacional saliente, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '3.Fortalecer los procesos de internacionalización, movilidad, multilingüismo e interculturalidad que visibilicen la Universidad a nivel nacional e internacional, y alcanzar un posicionamiento académico.', 'Internacionalización y multilingüismo.', 'Movilidad académica estudiantil y docente', 'Fortalecer la movilidad docente, desde las funciones sustantivas de docencia, extensión, proyección social e internacionalización, con un mínimo de 330 registros de movilidad saliente internacional y 660 de movilidad saliente nacional', 12.00, 'Promover la movilidad docente, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 15.00, 'Oficina de Rel. Interinst. e Internacionales', 'PDI', '0', 'Movilidad docente internacional saliente, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 'N° de docentes que realizaron movilidad saliente internacional, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '149', 34, '0', '34', '34.00', '13.00', 38.24, 13.00, NULL, 'Durante el primer semestre de 2026 (2026-I), la universidad impulsó el posicionamiento global de su cuerpo docente mediante 9 movilidades salientes internacionales, llevando a nuestros profesores a representar a la universidad en siete países (Estados Unidos, Austria, Italia, Francia, Brasil, Países Bajos y México), con un sobresaliente impacto de liderazgo científico, dado que 7 de los 9 docentes participaron como ponentes y expositores de alto nivel; los logros se detallan en dos facultades estratégicas: por un lado, en la Facultad de Ciencias Económicas (5 movilidades), el programa de Contaduría Pública logró la participación de tres de sus docentes como ponentes en el prestigio congreso The Critical Perspectives on Accounting en la Universidade Federal do Rio de Janeiro (Brasil), mientras que en el programa de Economía, un docente expuso en el 7th Symposium on Circular Economy and Sustainability (CESUST 2026) en la Maastricht School of Management (Países Bajos) y otra docente participó como ponente en el Coloquio Internacional México y Colombia en la Universidad Autónoma Metropolitana (México); por otro lado, en la Facultad de Ciencias Básicas (4 movilidades), el programa de Física destacó con la actualización de uno de sus docentes en la Universidad de California, Irvine (EE. UU.) y la ponencia de otro investigador ante Elsevier en Viena (Austria), el programa de Química proyectó su investigación mediante una conferencia ponente en el Congreso Internacional Catalysis Science (Italia) en alianza con Prism Scientific Services, y el programa de Biología fortaleció sus redes de investigación participando en el XIII European Congress of Entomology de la French Entomological Society en Tours (Francia). A traves de movilidad Administrativa:-La doctora Maralex Martinez se movilizo al evento Nafsa en Orlando Florida.\n-La decana Cristina Moltalvo fue como ponente al workshop Alemania Laypzig.\n-La docente Marcela Arellano se movilizo a Toledo España a un curso Internacional Sistemas juridicos y politicos de America Latina y relacioes con Canadá.\n-La doctora Maralex Martinez se movilizo a Canadá a misión Académica.', 'Existe una limitante con el reporte, debido a que algunas facultades nisiquiera reportan, y hay otras movilidades a las que se le ha tenido que hacer seguimiento especifico para poder adquirir la información de manera atomizada y asi unificarla, lo que genera menos reportes.', '', 'Articulación con las vicerrectorias para la recolección de la información y seguimiento para garantizar muchos mas reportes.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+9, @formulario, 'Movilidad docente nacional saliente, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '3.Fortalecer los procesos de internacionalización, movilidad, multilingüismo e interculturalidad que visibilicen la Universidad a nivel nacional e internacional, y alcanzar un posicionamiento académico.', 'Internacionalización y multilingüismo.', 'Movilidad académica estudiantil y docente', 'Fortalecer la movilidad docente, desde las funciones sustantivas de docencia, extensión, proyección social e internacionalización, con un mínimo de 330 registros de movilidad saliente internacional y 660 de movilidad saliente nacional', 12.00, 'Promover la movilidad docente, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 15.00, 'Oficina de Rel. Interinst. e Internacionales', 'PDI', '0', 'Movilidad docente nacional saliente, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 'N° de docentes de la Universidad del Atlántico que realizaron movilidad saliente nacional, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '316', 67, '0', '67', '67.00', '30.00', 44.78, 30.00, NULL, 'Durante el primer semestre de 2026 (2026-I), la institución impulsó el posicionamiento académico, la investigación y la articulación interinstitucional en el país mediante 30 movilidades salientes nacionales de docentes hacia ocho ciudades y municipios estratégicos (Bogotá, Santa Marta, Cartagena, Cali, Medellín, Montería, Valledupar y Zapayán), con un impacto sobresaliente detallado en tres facultades: en primer lugar, en la Facultad de Bellas Artes (15 movilidades), el programa de Danza lideró una intensa agenda que incluyó la participación artística en el Carnaval al Mayor en el Teatro Mayor Julio Mario Santo Domingo, una estancia investigativa de inmersión en territorio en Zapayán, y una misión académica con un taller de intercambio que movilizó a 13 docentes hacia la Facultad de Artes ASAB de la Universidad Francisco José de Caldas (Bogotá); en segundo lugar, en la Facultad de Ciencias Básicas (8 movilidades), el programa de Biología destacó con cinco representaciones que abarcaron una estancia investigativa en el INVEMAR (Santa Marta), una ponencia en la Universidad del Magdalena y la asistencia a eventos de alto nivel en las universidades Nacional de Colombia (sedes Bogotá y La Paz) y de Medellín, el programa de Química participó con un ponente en el Taller de Química Medicinal en la Universidad del Magdalena, el programa de Física proyectó su investigación con un ponente en la Universidad de Córdoba (Montería), y el programa de Matemáticas hizo presencia en la Cuarta Conferencia Colombiana de Matemáticas en Cali; finalmente, en la Facultad de Ciencias Económicas (7 movilidades), el programa de Contaduría Pública movilizó a cuatro profesores en una visita académica y de cooperación a la Universidad de Cartagena, el pregrado en Administración de Empresas posicionó a dos docentes como ponentes en la Conferencia Internacional ASCOLFA 2026 en la Universidad EAN (Bogotá), y el posgrado de Maestría en Economía sobresalió con una docente ponente en el evento de relevancia nacional 2026+: Finanzas para la Vida, organizado conjuntamente por el Departamento Nacional de Planeación (DNP) y la Universidad de los Andes en Bogotá.', 'Existe una limitante con el reporte, debido a que algunas facultades nisiquiera reportan, y hay otras movilidades a las que se le ha tenido que hacer seguimiento especifico para poder adquirir la información de manera atomizada y asi unificarla, lo que genera menos reportes.', '', 'Seguimiento a los requerimientos de información a la facultades y a la Vicerrectoria de bienestar que realiza gran numero de movilidades docentes nacionales pero que mayoritariamente no son reportadas.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+10, @formulario, 'Movilidad docente internacional entrante, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '3.Fortalecer los procesos de internacionalización, movilidad, multilingüismo e interculturalidad que visibilicen la Universidad a nivel nacional e internacional, y alcanzar un posicionamiento académico.', 'Internacionalización y multilingüismo.', 'Movilidad académica estudiantil y docente', 'Fortalecer la movilidad docente entrante internacional, desde las funciones sustantivas de docencia, extensión, proyección social e internacionalización', 12.00, 'Promover la movilidad docente, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 10.00, 'Oficina de Rel. Interinst. e Internacionales', 'PA', '0', 'Movilidad docente internacional entrante, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 'N° de docentes que realizaron movilidad entrante internacional, desde las funciones sustantivas docencia, extensión, proyección social e internacionalización', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '253', 30, '0', '30', '30.00', '15.00', 50.00, 15.00, NULL, 'Durante el primer semestre de 2026 (2026-I), la universidad  consolidó su proyección global y cooperación académica mediante la recepción de 14 docentes, artistas y expertos internacionales procedentes de siete países (Ecuador, Panamá, Estados Unidos, Brasil, Francia, Costa Rica y Sudáfrica), impactando de manera directa cuatro programas académicos de las facultades de Educación y Bellas Artes; entre los logros principales destacan la acogida de nueve docentes extranjeros en la Licenciatura en Ciencias Naturales para el Encuentro de Cooperación del Observatorio Iberoamericano de Ambiente Sostenible, el fortalecimiento y gestión de alianzas estratégicas para el pregrado en Lenguas Extranjeras con la Université de Poitiers (Francia), la asesoría académica de la Universidade Federal da Bahia (Brasil) para la estructura y desarrollo de posgrados en el programa de Danza, y el enriquecimiento cultural y artístico del programa de Música gracias a la participación de tres artistas de talla mundial como invitados en el ciclo institucional Concierto del Mes. \n-De la Universidad de Poitiers de Francia nos viisto la profeosra Liseth Marie Agnes sega.', 'Existe una limitante con el reporte, debido a que algunas facultades nisiquiera reportan, y hay otras movilidades a las que se le ha tenido que hacer seguimiento especifico para poder adquirir la información de manera atomizada y asi unificarla, lo que genera menos reportes.', '', 'Seguimiento a las actividades que se realicen en el campus para hacerle un seguimiento eficiente a este tipo de movilidades', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+11, @formulario, 'Porcentaje de programas académicos que desarrollan actividades con componente internacional en el aula (clases espejo, proyectos de aprendizaje colaborativo, actividades con comunidades académicas homólogas; entre otros) y extracurricular (seminarios, talleres, ferias, encuentros; entre otros).', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '8.Implementar iniciativas de colaboración entre instituciones de educación superior y universidades, incluidas las cooperativas de investigación y desarrollo de productos tecnológicos, así como la creación de espacios de intercambio de experiencias y conocimientos.', 'Internacionalización y multilingüismo.', 'Internacionalización en casa y curricular', 'Propender para que el 60% de los programas desarrollen actividades con componente internacional desde el aula y de manera extracurricular.', 6.00, 'Impulsar el desarrollo de actividades académicas con componente internacional', 35.00, 'Oficina de Rel. Interinst. e Internacionales', 'PDI', '0', 'Porcentaje de programas académicos que desarrollan actividades con componente internacional en el aula (clases espejo, proyectos de aprendizaje colaborativo, actividades con comunidades académicas homólogas; entre otros) y extracurricular (seminarios, talleres, ferias, encuentros; entre otros).', 'N° de programas académicos que desarrollan actividades con  componente internacional en el aula de clases l / total de programas académicos *100                              (clases espejo, proyectos de aprendizaje colaborativo, actividades con comunidades académicas homólogas; entre otros)', 'Anual', 'Porcentaje', 'Último valor reportado', 'Programas de pregrado', '[]', '24%', 34, '0%', '34%', '34.00', '12.00', 35.29, 12.00, NULL, 'Programa de Lic. en Educación especial realizó dos sesiones de clases espejo con la Universidad de Guadalajara, México.  \n2. Programa de Ingeniería Industrial realizó tres sesiones de clases espejo en diferentes temáticas, con la Universidad Autónoma del Caribe, Universidad Simón Bolívar, Universidad de la Guajira. \n3. Programa de Ingeniería Química realizó dos sesiones de clases espejo con la Universidad de la Guajira.\n4. Administración de Empresas  Turísticas realizó dos sesiones de clases espejo con la Universidad Católica de Salta, Argentina.\n5. Contaduría Pública realizó dos sesiones de clases espejo con la Universidad del Sinú, seccional Cartagena.\n6. Administración de empresas realizó una sesión de clase espejo con la Universidad de la Guajira.', 'El límite predominante es la diferencia de horario en el que se imparten las clases en cada Universidad. Asimismo, cuando se contacta a la Universidad par no hay una respuesta, o cuando se establece el primer encuentro el docente no asiste.', 'Se han  adelantado gestiones para el desarrollo de 3 COIL en los programas de Ingeniería Industrial, Arte Dramático e Ingeniería de Agronegocios (los últimos dos programas no ha realizado este tipo de estrategias). Asimismo, se han adelantado encuentros para realizar clases espejo con el programa de Farmacia, Arquitectura, Biología, Medicina, Historia, Lic. en Música, y Lic. en Naturales.', 'Establecer reuniones con los coordinadores y docentes de cada programa para que aprovechen estas estrategias y las incorporen en el componente internacional de su syllabus.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+12, @formulario, 'Porcentaje de programas académicos que desarrollan actividades con componente internacional en el aula (clases espejo, proyectos de aprendizaje colaborativo, actividades con comunidades académicas homólogas; entre otros) y extracurricular (seminarios, talleres, ferias, encuentros; entre otros).', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '8.Implementar iniciativas de colaboración entre instituciones de educación superior y universidades, incluidas las cooperativas de investigación y desarrollo de productos tecnológicos, así como la creación de espacios de intercambio de experiencias y conocimientos.', 'Internacionalización y multilingüismo.', 'Internacionalización en casa y curricular', 'Propender para que el 60% de los programas desarrollen actividades con componente internacional desde el aula y de manera extracurricular.', 6.00, 'Impulsar el desarrollo de actividades académicas con componente internacional', 35.00, 'Oficina de Rel. Interinst. e Internacionales', 'PDI', '0', 'Porcentaje de programas académicos que desarrollan actividades con componente internacional en el aula (clases espejo, proyectos de aprendizaje colaborativo, actividades con comunidades académicas homólogas; entre otros) y extracurricular (seminarios, talleres, ferias, encuentros; entre otros).', 'N° de programas académicos que  desarrollan actividades extracurriculares con componente internacional / total de programas académicos *100\n\n(seminarios, talleres, ferias, encuentros; entre otros).', 'Anual', 'Porcentaje', 'Último valor reportado', '', '[]', '46%', 13, '0%', '13%', '13.00', '9.00', 69.23, 9.00, NULL, 'En el 2026-1 se lograron 19 eventos con 10 programas diferentes.\nORII (3)\nCharla informativa: Educacion First.\nSocialización de Convocatoria CYTED, 2026.\nWebinar: Innovar la práctica docente desde la Internacionalización del Currículo\nMúsica (3)\nConcierto del mes: Apropiación Social del Conocimiento\nConcierto del mes: Apropiación Social del Conocimiento\nConcierto del mes: Apropiación Social del Conocimiento\nAdministración de Empresas Turísticas (3)\nTurismo sostenible: De la planificación a la implementación global.\nV Feria Universitaria Turísticas FUTUR 2026: Rediseñando el Turismo con Educación Ambiental e Inteligencia Artificial\n3er Encuentro Modelo Naciones Unidas: Turismo sostenible, resilencia territorial y desarrollo inclusivo en América Latina y el Caribe hacia 2035.\nAdministración de Empresas (1)\nConversatorio virtual sobre dinámicas globales y su impacto en las empresas colombianas.\nEconomía (2)\nGeneración ODS Caribe: Investigaciones de jóvenes estudiantes de economía\nSeminario Permanente ODS: Reconfiguración de las cadenas productivas de China los aranceles de Estados Unidos.\nMaestría en Economía (1)\nSeminario Permanente ODS: Reconfiguración de las cadenas productivas de China los aranceles de Estados Unidos.\nHistoria (4)\nI Ciclo de Palestras: Cartografías del Multilingüismo: Políticas Lingüísticas y revitalización en contestos interculturales.\nMuestra documental IEFA, 2026.\nI Ciclo de Palestras: Entre Palenques e Quilombos: Transculturalidad políticas lingüísticas y resistencia.\nCine, memoria, y diáspora en el Atlántico negro. Brasil: ecos de la abolición.\nFarmacia (2)\nHabilidades blancas: el diferencial del farmacéutico del alto impacto.\nFarmacéuticos en la era de la IA: Adaptarse o quedarse dispensando excusas.\nDerecho (2)\nCharla informativa: COIBA-AIP y COLACMAR 2026.\nJornada Internacional de Derecho Público: Autonomía Territorial en España y Colombia. 35 años de la Constitución Política de 1991.\nIngeniería Agroindustrial (1)\nSimposio Internacional de Innovación Agroindustrial: Alimentos funcionales: Experiencia de percepción y aceptación del consumidor.\nIngeniería Industrial (1)\nSimposio Internacional de Innovación Agroindustrial: Alimentos funcionales: Experiencia de percepción y aceptación del consumidor.', 'Falta de reporte de las facultades no permite ver el valor real de las actividades', 'Todavía nos encontramos obteniendo datos de las facultades.\n\nLa diferencia entre los eventos de las facultades y de los programas es que algunos eventos de la ORII impactan institucionalmente, tal como la Charla Informativa de con Education First, la\nSocialización de Convocatoria CYTED, 2026., y el  Webinar: Innovar la práctica docente desde la Internacionalización del Currículo.', 'Establecer reuniones con los gestores de internacionalización para el apoyo de reporte de actividades.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+13, @formulario, 'Actividades extracurriculares con componente internacional realizadas por Facultad (seminarios, talleres, ferias, encuentros, foros, congresos, concursos; entre otros)', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '8.Implementar iniciativas de colaboración entre instituciones de educación superior y universidades, incluidas las cooperativas de investigación y desarrollo de productos tecnológicos, así como la creación de espacios de intercambio de experiencias y conocimientos.', 'Internacionalización y multilingüismo.', 'Internacionalización en casa y curricular', 'Propender para que el 60% de los programas desarrollen actividades con componente internacional desde el aula y de manera extracurricular.', 6.00, 'Impulsar el desarrollo de actividades académicas con componente internacional', 30.00, 'Oficina de Rel. Interinst. e Internacionales', 'PDI-PA', '1', 'Actividades extracurriculares con componente internacional realizadas por Facultad (seminarios, talleres, ferias, encuentros, foros, congresos, concursos; entre otros)', 'N° de actividades extracurriculares con componente internacional realizadas por facultad (seminarios, talleres, ferias, encuentros, foros, congresos, concursos; entre otros)', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Arquitectura 6\nBellas Artes 3\nEconomicas  8\nbásicas  7\nHumanas  7\nC. de la Salud 4  \nFarmacia 3\nJurídica 5\nEducación  10\nIngenieiría 3', '[]', '58', 56, '0', '56', '56.00', '18.00', 32.14, 18.00, NULL, 'En el 2026-1, 6 facultades participaron en eventos este semestre:\nORII (3)\nCharla informativa: Educacion First.\nSocialización de Convocatoria CYTED, 2026.\nWebinar: Innovar la práctica docente desde la Internacionalización del Currículo\nBellas Artes (3)\nMúsica (3)\nConcierto del mes: Apropiación Social del Conocimiento\nConcierto del mes: Apropiación Social del Conocimiento\nConcierto del mes: Apropiación Social del Conocimiento\nCiencias Económicas (6)\nAdministración de Empresas Turísticas (3)\nTurismo sostenible: De la planificación a la implementación global.\nV Feria Universitaria Turísticas FUTUR 2026: Rediseñando el Turismo con Educación Ambiental e Inteligencia Artificial\n3er Encuentro Modelo Naciones Unidas: Turismo sostenible, resilencia territorial y desarrollo inclusivo en América Latina y el Caribe hacia 2035.\nAdministración de Empresas (1)\nConversatorio virtual sobre dinámicas globales y su impacto en las empresas colombianas.\nEconomía - Maestría en Economía (2)\nGeneración ODS Caribe: Investigaciones de jóvenes estudiantes de economía\nSeminario Permanente ODS: Reconfiguración de las cadenas productivas de China los aranceles de Estados Unidos.\nCiencias Humanas (4)\nHistoria (4)\nI Ciclo de Palestras: Cartografías del Multilingüismo: Políticas Lingüísticas y revitalización en contestos interculturales.\nMuestra documental IEFA, 2026.\nI Ciclo de Palestras: Entre Palenques e Quilombos: Transculturalidad políticas lingüísticas y resistencia.\nCine, memoria, y diáspora en el Atlántico negro. Brasil: ecos de la abolición.\nQuímica y Farmacia (2)\nFarmacia (2)\nHabilidades blancas: el diferencial del farmacéutico del alto impacto.\nFarmacéuticos en la era de la IA: Adaptarse o quedarse dispensando excusas\nCiencias Jurídicas (2)\nDerecho(2)\nCharla informativa: COIBA-AIP y COLACMAR 2026.\nJornada Internacional de Derecho Público: Autonomía Territorial en España y Colombia. 35 años de la Constitución Política de 1991.\nIngeniería (1)\nIngeniería Agroindustrial - Ingeniería Industrial (1)\nSimposio Internacional de Innovación Agroindustrial: Alimentos funcionales: Experiencia de percepción y aceptación del consumidor.', 'Falta de reporte de las facultades no permite ver el valor real de las actividades', 'Todavía nos encontramos obteniendo datos de las facultades.\n\nLa diferencia entre los eventos de las facultades y de los programas es que algunos eventos de la ORII impactan institucionalmente, tal como la Charla Informativa de con Education First, la\nSocialización de Convocatoria CYTED, 2026., y el  Webinar: Innovar la práctica docente desde la Internacionalización del Currículo.', 'Establecer reuniones con los gestores de internacionalización para el apoyo de reporte de actividades.', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+14, @formulario, 'Diseño e implementación de la Política de uso y apropiación de las TIC en la Universidad del Atlántico', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '5.Fortalecer políticas curriculares con pedagogías adecuadas que atiendan al principio de calidad académica con enfoque inclusivo a través del desarrollo de las disciplinas y las profesiones, la integración de saberes, el fortalecimiento de competencias digitales, la solución de problemas y la inserción de los egresados al mercado laboral.', 'Transformación digital', 'Competencias digitales', 'Implementar la Política de uso y apropiación de las TIC en la Universidad del Atlántico', 5.00, 'Implementar la Política de uso y apropiación de las TIC', 30.00, 'Dpto. de Edu. Virt. Medios Educ y Audiov', 'PDI', '0', 'Diseño e implementación de la Política de uso y apropiación de las TIC en la Universidad del Atlántico', 'N° de lineamientos implementados de la Política / total de lineamientos de la Política de uso y apropiación de las TIC en la Universidad del Atlántico * 100', 'Anual', 'Porcentaje', 'Último valor reportado', 'La venta de servicio por extensión - modalidad virtual \n\nCrear una red de investigadores de usos pe´dagogico  de TIC\n\nDe los 13 . 11 serán implementados', '[]', '77%', 80, '0%', '80%', '80.00', '69.23', 86.54, 69.23, NULL, 'SEMESTRE 1\n De acuerdo con la información reportada en el anexo de actividades y gestiones del periodo evaluado, se ha realizado la correspondencia de las evidencias y actividades ejecutadas frente a los 13 lineamientos totales de la Política de Uso y Apropiación de las TIC de la Universidad del Atlántico. Bajo la directriz de que 11 de los 13 lineamientos están programados para ser implementados, los resultados del cálculo del indicador son los siguientes:\n11 / 13                                                       84.6%                  \nPROGRESO DE PLANIFICACIÓN             META DE IMPLEMENTACIÓN   \n9 de 11\n                     LINEAMIENTOS CON EJECUCIÓN ACTIVA\n\nSi se calcula el cumplimiento real de los lineamientos implementados frente a los planificados en este ciclo, se cuenta con una ejecución activa y documentada en 9 lineamientos de los 11 programados (81.8% de efectividad de la meta), equivalentes al 69.2% del total de la política (9 de 13).', 'Se debe de tener una estrategia para estos lineamientos con todas las dependencias que se encuentran ya que aun no asimilan la parte de educación virtual en esta universidad', 'RESUMEN CUALICUANTITATIVO IMPLEMENTACIONPOLITICAS.docx', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+15, @formulario, 'N° de prácticas de innovación educativa con TIC por programa académico', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '5.Fortalecer políticas curriculares con pedagogías adecuadas que atiendan al principio de calidad académica con enfoque inclusivo a través del desarrollo de las disciplinas y las profesiones, la integración de saberes, el fortalecimiento de competencias digitales, la solución de problemas y la inserción de los egresados al mercado laboral.', 'Transformación digital', 'Competencias digitales', 'Lograr que al menos el 50% de los programas académicos apliquen prácticas de innovación educativa, y crear al menos 800 recursos digitales para la docencia con impacto positivo en la población y 20 herramientas digitales educativas habilitados por la UA\n(Ejemplos: aplica aprendizaje inverso, automatización de las prácticas de laboratorio, simuladores, plataformas, construcción de ebook)', 5.00, 'Fomentar las prácticas de innovación educativa mediadas por las TIC', 35.00, 'Dpto. de Edu. Virt. Medios Educ y Audiov', 'PDI-PA', '1', 'N° de prácticas de innovación educativa con TIC por programa académico', 'N° de prácticas de innovación educativa con TIC desarrolladas con Facultad', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Diagnostico de los estados de continuidad de las experiencias identificadas\n\nidentificación de experiencias que requieran apoyo para investigación y continuidad\n\nProcurar que los programas técnicos de la Facultades se incluyan y adémas 9 programas que no han realizado experiencias \n\nArquitectura 2\nBellas Artes 2\nEconomicas 1\nbásicas 2\nHumanas 2\nC. de la Salud 3\nFarmacia 2\nJurídica 2\nEducación 4\nIngenieiría 2', '[]', '41', 25, '0', '25', '25.00', '0.00', 0.00, 0.00, NULL, 'SEMESTRE 1  \nNos encontramos en la construcción de los términos de referencia para la convocatoria del V encuentro de innovación educativa donde se evidenciarían el numero de practicas de innovación educativa, la cual se desarrollará el 22 y 23 de septiembre de 2026 se han realizado 7 reuniones una de ella con GOOGLE como estrategia para el evento\nDado que el seguimiento institucional se dividirá en tres entregas de seguimiento a lo largo del año, esta primera entrega se establece como la medición inicial (línea base) con un peso equivalente al 33.3% del avance anual, proyectando el cumplimiento total hacia el V Encuentro de Innovación Educativa a realizarse el 22 y 23 de septiembre de 2026.', 'El apoyo de todas las dependencias para que todo este indicador se cumpla', 'Convocatoria V Encuentro de Innovacion 2026-10-07-2026.docx', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
