(@base+49, @formulario, 'Tasa de graduación acumulada.', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '5.Fortalecer políticas curriculares con pedagogías adecuadas que atiendan al principio de calidad académica con enfoque inclusivo a través del desarrollo de las disciplinas y las profesiones, la integración de saberes, el fortalecimiento de competencias digitales, la solución de problemas y la inserción de los egresados al mercado laboral.', 'Autoevaluación y acreditación Institucional y de programas académicos en el contexto nacional e internacional', 'Gestión y mejoramiento curricular', 'Implementar al menos  un 70%  de las estrategias académico administrativas dirigidas a la permanencia para alcanzar un 60% en la tasa graduación de los estudiantes.', 5.00, 'Gestionar la graduación oportuna.', 20.00, 'Dpto. Calidad Académica', 'PDI', '0', 'Tasa de graduación acumulada.', '(N° de estudiantes graduados acumulados de todas las cohortes hasta el periodo t / Total de estudiantes acumulados de primer ingreso de todas las cohortes hasta el periodo t) * 100.', 'Anual', 'Porcentaje', 'Último valor reportado', '', '[]', '48.6%', 5, '0%', '5%', '5.00', '43.00', 860.00, 43.00, NULL, '', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+50, @formulario, 'Concurso docente público de méritos', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '5.Fortalecer políticas curriculares con pedagogías adecuadas que atiendan al principio de calidad académica con enfoque inclusivo a través del desarrollo de las disciplinas y las profesiones, la integración de saberes, el fortalecimiento de competencias digitales, la solución de problemas y la inserción de los egresados al mercado laboral.', 'Autoevaluación y acreditación Institucional y de programas académicos en el contexto nacional e internacional', 'Fortalecimiento de las capacidades del capital humano docente', 'realizar al menos 2 concursos públicos de mérito con resultados de 80% de efectividad.', 6.00, 'Evaluar la efectividad del concurso docente', 20.00, 'Vicerrectoría de Docencia', 'PDI', '0', 'Concurso docente público de méritos', 'N° de concursos docente público de méritos', 'Anual', 'Unidad', 'Nuevo gestionado durante la vigencia', '', '[]', '0', 1, '0', '1', '1.00', '0.00', 0.00, 0.00, NULL, '', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+51, @formulario, 'Efectividad del concurso docente', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '7.Fortalecer la metodología de investigación y la participación activa en proyectos de investigación y desarrollo de productos tecnológicos para lograr un mayor reconocimiento regional y la competitividad nacional e internacional.', 'Autoevaluación y acreditación Institucional y de programas académicos en el contexto nacional e internacional', 'Fortalecimiento de las capacidades del capital humano docente', 'realizar al menos 2 concursos\npúblicos de mérito con resultados\nde 80% de efectividad.', 6.00, 'Fortalecer la planta docente', 20.00, 'Vicerrectoría de Docencia', 'PDI', '0', 'Efectividad del concurso docente', 'N° de plazas cubiertas / total de plazas ofertadas* 100', 'Anual', 'Porcentaje', 'Último valor reportado', 'Se ofertaran 100 plazas, para el concurso 2026 de 247 que se requieren', '[]', '80%', 80, '0%', '80%', '80.00', '0.00', 0.00, 0.00, NULL, '', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+52, @formulario, 'Porcentaje de docentes de carrera profesoral con nivel de formación de doctorado.', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '7.Fortalecer la metodología de investigación y la participación activa en proyectos de investigación y desarrollo de productos tecnológicos para lograr un mayor reconocimiento regional y la competitividad nacional e internacional.', 'Autoevaluación y acreditación Institucional y de programas académicos en el contexto nacional e internacional', 'Fortalecimiento de las capacidades del capital humano docente', 'Alcanzar el 60% de nivel de formación doctoral y un 40% de maestría de la planta docente (carrera profesoral).', 6.00, 'Fortalecer la planta docente', 20.00, 'Vicerrectoría de Docencia', 'PDI', '0', 'Porcentaje de docentes de carrera profesoral con nivel de formación de doctorado.', 'N° de docentes de carrera profesoral con nivel de formación de doctorado / total de docentes de carrera profesoral * 100', 'Anual', 'Porcentaje', 'Último valor reportado', '', '[]', '40%', 40, '0%', '40%', '40.00', '45.00', 112.50, 45.00, NULL, 'De un total de 350 docentes de carrera profesoral de la Universidad, 159 cuentan con título de doctorado, lo que representa el 45.42 % del total de docentes de carrera.', '', '', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+53, @formulario, 'Porcentaje de docentes de carrera profesoral con nivel de formación de maestría.', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '6.Integrar los procesos académicos y administrativos que conlleve de manera funcional a un orden adecuado de interacciones, soportadas en tecnologías de la información, de acuerdo a la normatividad vigente.', 'Autoevaluación y acreditación Institucional y de programas académicos en el contexto nacional e internacional', 'Fortalecimiento de las capacidades del capital humano docente', 'Alcanzar el 60% de nivel de\nformación doctoral y un 40% de\nmaestría de la planta docente\n(carrera profesoral).', 6.00, 'Docentes certificados mediante las actividades de capacitación o cualificación docente por año', 20.00, 'Vicerrectoría de Docencia', 'PDI', '0', 'Porcentaje de docentes de carrera profesoral con nivel de formación de maestría.', 'N° de docentes de carrera profesoral con nivel de formación de maestría / total de docentes de carrera profesoral * 100', 'Anual', 'Porcentaje', 'Nuevo gestionado durante la vigencia', '', '[]', '40%', 40, '0%', '40%', '40.00', '36.00', 90.00, 36.00, NULL, 'De un total de 350 docentes de carrera profesoral de la Universidad, 127 cuentan con título de maestría, lo que representa el 36,28 % del total de docentes de carrera.', '', '. Se estima que, con la apertura del concurso docente, este indicador presente un incremento, debido a la vinculación de nuevos docentes con formación de maestría, lo que contribuirá al fortalecimiento de la calidad académica y al cumplimiento de las metas institucionales.', '', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1),
(@base+54, @formulario, 'Docentes certificados mediante las actividades de capacitación o cualificación docente por año', 2026, 'Formación Académica Integral', 'Garantizar la formación en educación superior de manera integral e inclusiva, con calidad, pertinencia, flexibilidad, interdisciplinariedad, competencias digitales, internacionalización, multilingüismo e interculturalidad, mediante procesos de autorregulación sostenible y con perspectiva regional.', '7.Fortalecer la metodología de investigación y la participación activa en proyectos de investigación y desarrollo de productos tecnológicos para lograr un mayor reconocimiento regional y la competitividad nacional e internacional.', 'Autoevaluación y acreditación Institucional y de programas académicos en el contexto nacional e internacional', 'Fortalecimiento de las capacidades del capital humano docente', 'Alcanzar la certificación de al menos 900 docentes  mediante las actividades de capacitación o cualificación docente.', 6.00, 'Fortalecer la inducción docente, y promover diálogos intergeneracionales y encuentros de experiencia, como actividad integradora a la carrera profesoral para docentes que ingresan por primera vez a la universidad.', 20.00, 'Vicerrectoría de Docencia', 'PR', '1', 'Docentes certificados mediante las actividades de capacitación o cualificación docente por año', 'N° de docentes certificados como resultado de las actividades de capacitación o cualificación docente realizadas al año', 'Semestral', 'Unidad', 'Nuevo gestionado durante la vigencia', 'Arquitectura: 35\nBellas Artes: 30\nCiencias Economicas: 60\nCiencias Basicas:80\nCiencias Humanas:80\nCiencias de la salud:30\nQuimica y farmacia:20\nCiencias Juridica:50\nEducación:100\nIngenieria:60\n\nlos docentes certificados no no se repiten de un semestre a otro, eso quiere decir que un docente solo contaria una vez por año', '[]', '837', 545, '0', '545', '545.00', '450.00', 82.57, 450.00, NULL, 'A corte de fecha 30 de junio de 2026. se ca